GRADES = ('VERBATIM', 'VARIANT', 'TURNED', 'SHORTENED', 'EXPANDED', 'SUPPLIED', 'DISAGREES')
def rb(verses, told, grade, why, tape_kind=None, tape_verse=None, cell=None, cell_found=None, entry='', open_=False, ledger_scan=None):
    assert grade in GRADES, grade
    if grade == 'SUPPLIED':
        assert tape_kind is None and cell is None and ledger_scan in ([], None), ('a SUPPLIED state has no line, no cell, and an empty scan', verses, ledger_scan)
    else:
        assert (tape_kind is None) != (cell is None), ('one of the tape or the cell', verses)
        if cell is not None: assert cell_found is True, ('the kin cell CALLED and found', verses, cell)
    return {'verses': verses, 'told': told, 'tape_kind': tape_kind, 'tape_verse': tape_verse, 'cell': cell, 'cell_found': cell_found, 'entry': entry, 'grade': grade, 'why': why, 'open': open_, 'law': False, 'ledger_scan': ledger_scan}
