    if k == 'good_land_case':
        fn = {'frame': the_frame, 'forty': the_way_of_forty_years, 'land': the_good_land, 'heed': take_heed_lest_you_forget, 'chain': the_chain_and_the_covenant, 'testimony': the_testimony}[event['cell']]
